mapper.select:
/* Baim01Mapper.selectSiteInfoList */ SELECT '' AS chk , A.SITE_CD AS siteCd , A.SITE_NO AS siteNo , A.SITE_NM AS siteNm , A.CMPNY_CD AS cmpnyCd , A.ADDR_1 AS addr1 , A.ADDR_2 AS addr2 , A.ZIP_CODE AS zipCode , A.STR_DATE AS strDate , A.END_DATE AS endDate , A.USE_YN AS useYn , A.SITE_ADMIN_CD AS siteAdminCd , B.USER_NM AS siteAdminNm , A.TEL_NO AS telNo , IFNULL(A.GPS_RANGE, 0) AS gpsRange , A.SITE_DESC AS siteDesc , A.LAT AS lat , A.LON AS lon FROM TB_SITE A LEFT JOIN TB_USER B ON ( A.CMPNY_CD = B.CMPNY_CD AND A.SITE_ADMIN_CD = B.USER_CD ) WHERE 1=1 AND A.CMPNY_CD = #{gvCmpnyCd}
AND A.SITE_CD = #{siteCd}
AND A.SITE_NO = #{siteNo}
AND A.SITE_NM LIKE CONCAT('%', #{siteNm}, '%')
AND A.USE_YN = #{useYn}

mapper.insert:
/* Baim01Mapper.insertSiteNodeInfo */
INSERT INTO TB_SITE_NODE(
	CMPNY_CD
	, SITE_CD
	, NODE_CD
	, NODE_NM
	, NODE_TYPE
	, INSERT_NO
	, INSERT_DATE
	, UPDATE_NO
	, UPDATE_DATE
)
VALUES(
	#{gvCmpnyCd}
	, #{siteCd}
	, #{nodeCd}
	, #{nodeNm}
	, #{nodeType}
	, #{gvUserCd}
	, NOW()
	, #{gvUserCd}
	, NOW() 
) AS NEW
ON DUPLICATE KEY UPDATE
	NODE_NM 		= NEW.NODE_NM
	, UPDATE_NO		= NEW.UPDATE_NO
	, UPDATE_DATE 	= NEW.UPDATE_DATE
